namespace sv_5ebc86fd6e214f22a97137a53fa4edc3.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_5ebc86fd6e214f22a97137a53fa4edc3.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@activeChannelName"
                 ChannelDescription="@activeChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages"
                 class="@(threadOpen ? "main-area-with-thread" : "main-area-full")" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private List<Message> threadReplies = new();
    private Message? threadRootMessage;

    private int activeChannelId;
    private string activeChannelName = string.Empty;
    private string activeChannelDescription = string.Empty;
    private bool threadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannelId = channel.Id;
        activeChannelName = channel.Name;
        activeChannelDescription = channel.Description;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;
        threadSummaries = BuildThreadSummaries(messages);
        await ChatService.MarkChannelReadAsync(channel.Id);
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            threadSummaries = BuildThreadSummaries(messages);
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        // Update thread summary count
        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
        if (existing is not null)
        {
            threadSummaries.Remove(existing);
            threadSummaries.Add(existing with { ReplyCount = existing.ReplyCount + 1, LastReplyAt = reply.SentAt });
        }
        else
        {
            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt));
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Optimistic update
        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existingReaction = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existingReaction is not null)
            {
                existingReaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, new List<string> { "You" }));
            }
        }
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> msgs)
    {
        var replies = msgs.Where(m => m.ReplyToId.HasValue).ToList();
        return replies
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

