    padding: 4px;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #40444b;
}

/* Message Input */
.message-input-area {
    padding: 12px 20px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

.message-textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.send-btn {
    background: #5865f2;
